CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE operators (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), label text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE whatsapp_identities (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), value text NOT NULL UNIQUE, operator_id uuid NOT NULL REFERENCES operators(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, normalized_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX customers_normalized_name_idx ON customers(normalized_name);
CREATE SEQUENCE service_order_number_seq START 1;
CREATE TABLE service_orders (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), number integer NOT NULL UNIQUE DEFAULT nextval('service_order_number_seq'), customer_id uuid NOT NULL REFERENCES customers(id), description text NOT NULL CHECK (length(btrim(description)) > 0), amount_cents integer, status text NOT NULL CHECK (status IN ('AGUARDANDO_DADOS','AGUARDANDO_CONFIRMACAO','CONFIRMADA','CANCELADA')), created_at timestamptz NOT NULL DEFAULT now(), confirmed_at timestamptz, cancelled_at timestamptz);
CREATE TABLE conversation_states (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operator_id uuid NOT NULL UNIQUE REFERENCES operators(id), pending_action text, payload jsonb, service_order_id uuid REFERENCES service_orders(id), expires_at timestamptz, reply_to text, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operator_id uuid NOT NULL REFERENCES operators(id), session text NOT NULL, message_id text NOT NULL, reply_to text NOT NULL, body text, has_media boolean NOT NULL DEFAULT false, skipped_reason text, received_at timestamptz NOT NULL DEFAULT now(), UNIQUE(session,message_id));
CREATE TABLE webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), session text NOT NULL, message_id text NOT NULL, message_db_id uuid NOT NULL REFERENCES messages(id), state text NOT NULL DEFAULT 'PENDING' CHECK (state IN ('PENDING','PROCESSED','FAILED')), attempts integer NOT NULL DEFAULT 0, last_error text, raw jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), processed_at timestamptz, UNIQUE(session,message_id));
CREATE INDEX webhook_events_pending_idx ON webhook_events(state,created_at);
CREATE TABLE outbound_messages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), operator_id uuid NOT NULL REFERENCES operators(id), correlation_message_id uuid REFERENCES messages(id), reply_to text NOT NULL, body text NOT NULL, dedup_key text NOT NULL UNIQUE, status text NOT NULL DEFAULT 'PENDING' CHECK (status IN ('PENDING','LEASED','SENT','FAILED','UNCERTAIN')), attempts integer NOT NULL DEFAULT 0, provider_message_id text, last_error text, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT now(), sent_at timestamptz);
CREATE INDEX outbound_messages_delivery_idx ON outbound_messages(status,created_at);
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid NOT NULL REFERENCES operators(id), source_message_id uuid REFERENCES messages(id), entity_type text NOT NULL, entity_id text NOT NULL, action text NOT NULL, previous_status text, new_status text, reason text, created_at timestamptz NOT NULL DEFAULT now());
